insert into public.package_releases (listing_id, version, content) values ('l-free-nature-journal', 1, '{"units":[{"id":"nj-u1","title":"Week 1: Getting started","lessons":[{"id":"nj-1","title":"Your first journal page","steps":["Pick a sit spot outside","Sketch one thing for 10 minutes","Write the date, place, and weather"],"links":[],"questions":["What surprised you today?"]},{"id":"nj-2","title":"Leaves up close","steps":["Collect three different leaves","Trace and sketch them","Label the edges and veins"],"links":[],"questions":["How are your leaves alike? How are they different?"]}]},{"id":"nj-u2","title":"Week 2: Looking closer","lessons":[{"id":"nj-3","title":"Bark rubbings","steps":["Find two trees","Make a crayon rubbing of each","Sketch each tree’s shape"],"links":[],"questions":["Which bark felt roughest?"]},{"id":"nj-4","title":"Birds at the window","steps":["Watch a feeder or window for 15 minutes","Tally each bird you see","Sketch one bird"],"links":[],"questions":[]}]},{"id":"nj-u3","title":"Week 3: Weather and sky","lessons":[{"id":"nj-5","title":"Cloud watching","steps":["Lie back and watch the clouds","Sketch three cloud shapes","Note the wind and temperature"],"links":[],"questions":[]},{"id":"nj-6","title":"Shadows through the day","steps":["Trace a stick’s shadow in the morning","Trace it again at noon and afternoon","Draw the three shadows"],"links":[],"questions":["Why did the shadow change?"]}]},{"id":"nj-u4","title":"Week 4: Your place","lessons":[{"id":"nj-7","title":"A sit spot, revisited","steps":["Return to your first sit spot","Sketch what changed","Compare with your first page"],"links":[],"questions":[]},{"id":"nj-8","title":"Make a nature map","steps":["Walk your yard or park","Draw a map with your favorite spots","Add a key"],"links":[],"questions":["What do you want to watch next month?"]}]}],"version":1,"license":{"kind":"all_rights_reserved","holder":"Pinecone Science Co."}}'::jsonb);
