insert into public.listings (id, seller_name, seller_kind, seller_verified, title, subjects, grade_min, grade_max, philosophies, format, price, condition, description, includes, lessons, lessons_per_week, minutes_per_lesson, parent_involvement, family_style, lesson_steps, cover, color, esa_eligible, sample, created_at, package_id, package_version, license, attribution, outline) values ('l-fractions-workshop', 'Maple Room Studio', 'creator', false, 'Fractions Workshop: Hands-On Fractions', array['math']::text[], 2, 4, array['montessori', 'unit_study', 'traditional']::text[], 'digital', 9, null, 'Twelve hands-on lessons that build fractions from folding paper to story problems. Every lesson has a kid checklist and printable questions, made in Freerange Studio.', array['12 lessons in 3 units', 'Lesson-by-lesson plan that schedules into Freerange', 'Printable worksheet questions']::text[], 12, 3, 30, 'medium', false, '{}'::text[], '🍕', '#E3A33B', false, true, '2026-11-02T21:55:38.308Z', 'pk-l-fractions-workshop', 1, '{"kind":"cc_by","version":"4.0","holder":"Maple Room Studio"}'::jsonb, '“Fractions Workshop” by Maple Room Studio, licensed under CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/).', '[{"title":"Unit 1: Halves and wholes","lessons":["Fold it in half","Fair shares","Half of a number"]},{"title":"Unit 2: Thirds, fourths, and more","lessons":["Pizza fractions","Thirds with string","Fraction strips","Which is bigger?"]},{"title":"Unit 3: Equal fractions","lessons":["Same size, different names","Fractions in the kitchen","Fraction number line","Fraction story problems","Show what you know"]}]'::jsonb);
insert into public.package_releases (listing_id, version, content) values ('l-fractions-workshop', 1, '{"units":[{"id":"fw-u1","title":"Unit 1: Halves and wholes","lessons":[{"id":"fw-1","title":"Fold it in half","steps":["Fold paper shapes in half","Color one half","Write ½ on each"],"links":[],"questions":["Draw a shape that is NOT cut in half."],"minutes":25,"answers":["Any shape split into two unequal parts"],"notes":"Let them check by folding: halves match exactly when folded."},{"id":"fw-2","title":"Fair shares","steps":["Share 8 crackers between 2 people","Share 8 between 4","Draw what you did"],"links":[],"questions":[]},{"id":"fw-3","title":"Half of a number","steps":["Use counters to find half of 6, 10, 14","Find half of an odd number — what happens?"],"links":[],"questions":["What is half of 12?","What is half of 20?"],"answers":["6","10"]}]},{"id":"fw-u2","title":"Unit 2: Thirds, fourths, and more","lessons":[{"id":"fw-4","title":"Pizza fractions","steps":["Cut a paper pizza into 4 slices","Name each slice ¼","Eat (pretend!) 3 slices"],"links":[],"questions":["How much pizza is left?"]},{"id":"fw-5","title":"Thirds with string","steps":["Fold string into thirds","Measure each part"],"links":[],"questions":[]},{"id":"fw-6","title":"Fraction strips","steps":["Make strips for ½, ⅓, ¼, ⅙, ⅛","Line them up","Glue them into your notebook"],"links":[],"questions":[]},{"id":"fw-7","title":"Which is bigger?","steps":["Compare fractions with your strips","Play the “bigger fraction” card game"],"links":[],"questions":["Which is bigger, ⅓ or ¼?","Which is bigger, ½ or ⅝?"]}]},{"id":"fw-u3","title":"Unit 3: Equal fractions","lessons":[{"id":"fw-8","title":"Same size, different names","steps":["Find strips equal to ½","Write the matching fractions"],"links":[],"questions":["Name two fractions equal to ½."]},{"id":"fw-9","title":"Fractions in the kitchen","steps":["Measure ½ cup using ¼ cups","Measure ¾ cup two ways"],"links":[],"questions":[]},{"id":"fw-10","title":"Fraction number line","steps":["Draw a line from 0 to 1","Mark halves, fourths, eighths"],"links":[],"questions":[]},{"id":"fw-11","title":"Fraction story problems","steps":["Read each story","Draw a picture","Solve"],"links":[],"questions":["Mia ate ⅜ of a pie and Leo ate ⅛. How much did they eat together?"]},{"id":"fw-12","title":"Show what you know","steps":["Make a fraction poster","Teach a grown-up one thing you learned"],"links":[],"questions":[]}]}],"version":1,"license":{"kind":"cc_by","version":"4.0","holder":"Maple Room Studio"},"attribution":"“Fractions Workshop” by Maple Room Studio, licensed under CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/)."}'::jsonb);
insert into public.listings (id, seller_name, seller_kind, seller_verified, title, subjects, grade_min, grade_max, philosophies, format, price, condition, description, includes, lessons, lessons_per_week, minutes_per_lesson, parent_involvement, family_style, lesson_steps, cover, color, esa_eligible, sample, created_at, package_id, package_version, license, attribution, outline) values ('l-open-garden', 'Juniper & Co. Learning', 'creator', false, 'Open Garden Science (lesson plan)', array['science']::text[], 1, 5, array['nature_forest', 'unit_study']::text[], 'online', 0, null, 'A free online garden science course, organized into a ready-to-schedule plan with kid checklists. Adapted under the source’s Creative Commons license.', array['4 lessons in 2 units', 'Lesson-by-lesson plan that schedules into Freerange']::text[], 4, 2, 35, 'medium', true, '{}'::text[], '🌻', '#3D9970', false, true, '2026-11-08T21:55:38.309Z', 'pk-l-open-garden', 1, '{"kind":"cc_by_nc_sa","version":"4.0"}'::jsonb, 'Adapted from “Open Garden Science” by Open Garden Project (https://example.org/open-garden-science), licensed under CC BY-NC-SA 4.0 (https://creativecommons.org/licenses/by-nc-sa/4.0/). Organized into lessons by Juniper & Co. Learning.', '[{"title":"Seeds","lessons":["What’s inside a seed?","Sprouting in a jar"]},{"title":"Soil and roots","lessons":["Soil detectives","Root view window"]}]'::jsonb);
insert into public.package_releases (listing_id, version, content) values ('l-open-garden', 1, '{"units":[{"id":"gs-u1","title":"Seeds","lessons":[{"id":"gs-1","title":"What’s inside a seed?","steps":["Soak a bean overnight","Split it open","Sketch the parts"],"links":[{"label":"Open lesson","url":"https://example.org/open-garden-science/seeds-inside"}],"questions":[]},{"id":"gs-2","title":"Sprouting in a jar","steps":["Set up the jar","Check daily and draw"],"links":[{"label":"Open lesson","url":"https://example.org/open-garden-science/sprouting"}],"questions":[]}]},{"id":"gs-u2","title":"Soil and roots","lessons":[{"id":"gs-3","title":"Soil detectives","steps":["Shake soil in a jar of water","Wait an hour","Draw the layers"],"links":[{"label":"Open lesson","url":"https://example.org/open-garden-science/soil"}],"questions":[]},{"id":"gs-4","title":"Root view window","steps":["Plant a bean against a clear cup","Measure the root each day"],"links":[{"label":"Open lesson","url":"https://example.org/open-garden-science/roots"}],"questions":[]}]}],"version":1,"license":{"kind":"cc_by_nc_sa","version":"4.0"},"attribution":"Adapted from “Open Garden Science” by Open Garden Project (https://example.org/open-garden-science), licensed under CC BY-NC-SA 4.0 (https://creativecommons.org/licenses/by-nc-sa/4.0/). Organized into lessons by Juniper & Co. Learning."}'::jsonb);
